// ═══════════════════════════════════════════════════════
// KHỐI 4 — Nghiệp Vụ Nâng Cao (Analytics & AI)
// ExecutionType: AI, ANALYSIS, REPORT, SCORING
// Ví dụ: @goi_y_don_hang, @upsell_goi_y, @cham_diem_kh, @de_xuat_khuyen_mai
// Timeout cao hơn vì cần chờ AI xử lý phức tạp hơn
// ═══════════════════════════════════════════════════════
const raw = $input.item.json;
const body = raw.body || raw;
const headers = raw.headers || {};

const ApiCode = (body.ApiCode || '').trim();
const username = body.username || 'default';
const token = headers.authorization || body.token || 'Bearer empty';
const isConfirm = parseInt(body.isConfirm || '0', 10);

// params: AI Agent truyền lên dưới dạng JSON string hoặc object
let params = {};
if (typeof body.params === 'string') {
  try { params = JSON.parse(body.params); } catch(e) { params = {}; }
} else if (typeof body.params === 'object' && body.params !== null) {
  params = body.params;
}

// Inject @Username tự động
if (!params['@Username']) {
  params['@Username'] = username;
}

if (!ApiCode) {
  return [{ json: {
    loi: true,
    message: 'Thiếu ApiCode. Cần truyền ApiCode và params dạng JSON object.'
  }}];
}

return [{ json: {
  ApiCode,
  username,
  token,
  isConfirm,
  params,
  hop_le: true
}}];

const data = $input.item.json;
const ApiCode = $('Parse Input').item.json.ApiCode || '';

if (data.error || data.status === 'error') {
  return [{ json: {
    ket_qua: `❌ Lỗi phân tích [${ApiCode}]: ${data.message || data.error || 'Lỗi không xác định'}`,
    loi: true
  }}];
}

const payload = data.data || data.result || data.message || data;
let text = '';

if (typeof payload === 'string') {
  // Nâng cao thường trả dạng text phân tích/gợi ý → giữ nguyên
  text = payload;
} else if (Array.isArray(payload)) {
  const total = payload.length;
  if (total === 0) {
    text = 'Không có dữ liệu phân tích.';
  } else {
    const keys = Object.keys(payload[0]).filter(k => !k.startsWith('_'));
    text = `📊 Kết quả phân tích (${total} mục):\n\n`;
    text += `| STT | ${keys.join(' | ')} |\n`;
    text += `|---|${keys.map(() => '---').join('|')} |\n`;
    text += payload.slice(0, 20).map((row, i) => {
      return `| ${i + 1} | ${keys.map(k => {
        let val = row[k];
        if (val === null || val === undefined) return '';
        return String(val).replace(/\|/g, '-');
      }).join(' | ')} |`;
    }).join('\n');
    if (total > 20) text += `\n\n... và ${total - 20} mục khác.`;
  }
} else if (typeof payload === 'object') {
  // Object đơn (gợi ý, điểm chấm...) — format dễ đọc
  text = Object.entries(payload)
    .filter(([k]) => !k.startsWith('_'))
    .map(([k, v]) => `• **${k}**: ${v}`)
    .join('\n');
}

return [{ json: {
  ket_qua: text || 'Không có kết quả phân tích.',
  ApiCode,
  so_ban_ghi: Array.isArray(payload) ? payload.length : null
}}];

const data = $input.item.json;
return [{ json: {
  ket_qua: data.message || 'Yêu cầu không hợp lệ.',
  loi: true
}}];
